def transform(grid):
    """Repeat the largest non-key silhouette vertically using the key's colors."""
    h, w = len(grid), len(grid[0])

    # A key is a horizontal run of adjacent, differently colored solid vertical bars.
    bars = {}
    for c in range(w):
        occupied = [r for r in range(h) if grid[r][c] != 0]
        if len(occupied) < 2 or occupied != list(range(occupied[0], occupied[-1] + 1)):
            continue
        vals = {grid[r][c] for r in occupied}
        if len(vals) == 1:
            bars[c] = (occupied[0], occupied[-1] + 1, next(iter(vals)))
    candidates = []
    for c in sorted(bars):
        if c == 0 or c - 1 not in bars or bars[c - 1][:2] != bars[c][:2]:
            run = [c]
            while run[-1] + 1 in bars and bars[run[-1] + 1][:2] == bars[c][:2]:
                run.append(run[-1] + 1)
            colors = [bars[x][2] for x in run]
            if len(colors) >= 2 and len(set(colors)) == len(colors):
                candidates.append((run, bars[c][0], bars[c][1], colors))
    if not candidates:
        return [row[:] for row in grid]
    cols, key_top, key_bottom, palette = max(candidates, key=lambda item: len(item[0]))
    key_cells = {(r, c) for r in range(key_top, key_bottom) for c in cols}

    # Find monochrome components outside the key and choose the largest figure.
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in key_cells or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen
                            and (ny, nx) not in key_cells and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if color in palette:
                components.append((cells, color))
    if not components:
        return [row[:] for row in grid]

    cells, anchor_color = max(components, key=lambda item: len(item[0]))
    top = min(r for r, _ in cells)
    left = min(c for _, c in cells)
    bottom = max(r for r, _ in cells)
    right = max(c for _, c in cells)
    silhouette = {(r - top, c - left) for r, c in cells}
    figure_h = bottom - top + 1
    anchor_index = palette.index(anchor_color)

    out = [row[:] for row in grid]
    for r, c in key_cells:
        out[r][c] = 0
    for i, color in enumerate(palette):
        new_top = top + (i - anchor_index) * figure_h
        for dy, dx in silhouette:
            y, x = new_top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


