    h, w = len(grid), len(grid[0])

    # The palette is a short horizontal row of solid vertical color bars.
    runs = {}
    for c in range(w):
        r = 0
        while r < h:
            color = grid[r][c]
            if color == 0:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == color:
                r += 1
            if r - start >= 2:
                runs.setdefault((start, r), {})[c] = color

    keys = []
    for (top, bottom), bars in runs.items():
        for left in sorted(bars):
            if left - 1 not in bars:
                cols = [left]
                while cols[-1] + 1 in bars:
                    cols.append(cols[-1] + 1)
                colors = [bars[c] for c in cols]
                if len(colors) >= 2 and len(set(colors)) == len(colors):
                    keys.append((len(cols), bottom - top, top, bottom, cols, colors))
    if not keys:
        return [row[:] for row in grid]
    _, _, key_top, key_bottom, key_cols, palette = max(keys)
    key_cells = {(r, c) for r in range(key_top, key_bottom) for c in key_cols}

    # Extract same-color 8-connected shapes, excluding the palette.
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in key_cells or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny in range(max(0, y - 1), min(h, y + 2)):
                    for nx in range(max(0, x - 1), min(w, x + 2)):
                        if ((ny, nx) != (y, x) and (ny, nx) not in seen
                                and (ny, nx) not in key_cells and grid[ny][nx] == color):
                            seen.add((ny, nx))
                            stack.append((ny, nx))
            if color in palette:
                top = min(y for y, _ in cells)
                left = min(x for _, x in cells)
                shape = frozenset((y - top, x - left) for y, x in cells)
                sh = max(y for y, _ in shape) + 1
                sw = max(x for _, x in shape) + 1
                if sh >= 2 and sw >= 2:
                    objects.append((color, top, left, sh, sw, shape))
    if not objects:
        return [row[:] for row in grid]

    # The repeated motif is the largest silhouette; instances are vertically stacked.
    template = max(objects, key=lambda obj: (len(obj[5]), obj[3] * obj[4]))
    _, _, left, shape_h, _, shape = template
    matching = [obj for obj in objects if obj[5] == shape and obj[2] == left]
    bases = [obj[1] - palette.index(obj[0]) * shape_h for obj in matching]
    base_top = min(bases)

    out = [row[:] for row in grid]
    for r, c in key_cells:
        out[r][c] = 0
    for i, color in enumerate(palette):
        top = base_top + i * shape_h
        for dy, dx in shape:
            y, x = top + dy, left + dx
            if 0 <= y < h and 0 <= x < w:
                out[y][x] = color
    return out


